-- GERADO por scripts/gerar-catalogos.mjs a partir de supabase/functions/mcp/catalogos/*.json.
-- Não edite à mão: altere o JSON e gere de novo.

on conflict (codigo) do update set nome = excluded.nome, tipo = excluded.tipo,
  usa_faces = excluded.usa_faces, resolve = excluded.resolve, ordem = excluded.ordem;

on conflict (codigo) do update set ordem = excluded.ordem, grupo = excluded.grupo,
  texto = excluded.texto, tipo = excluded.tipo, detalhe = excluded.detalhe,
  alerta_tipo = excluded.alerta_tipo, alerta_texto = excluded.alerta_texto, ativa = true;
